// Every workflow in this project names this one as its error workflow.
// Recipients are set on the email node rather than read from the database,
// so the alert still goes out when the database is what failed.
const e = $input.first().json;
const esc = (v) => String(v ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const name = e.workflow?.name ?? 'unknown workflow';
const message = e.execution?.error?.message ?? e.trigger?.error?.message ?? 'No error message';
const node = e.execution?.lastNodeExecuted;
const url = e.execution?.url;

return [{
  json: {
    subject: `[Service Desk] Workflow failed: ${name}`,
    html: `<div style="font-family:Arial,sans-serif;font-size:14px">
      <p>The workflow <b>${esc(name)}</b> failed${node ? ` at node <b>${esc(node)}</b>` : ''}.</p>
      <p>Error: <code>${esc(message)}</code></p>
      ${url ? `<p><a href="${esc(url)}">Open the failed execution in n8n</a></p>` : ''}</div>`,
  },
}];
